```python
class Animal:
    def __init__(self, nombre):
        self._nombre = nombre          # encapsulación

    def hablar(self):
        raise NotImplementedError()    # polimorfismo

class Perro(Animal):
    def hablar(self):
        return "Guau"

class Gato(Animal):
    def hablar(self):
        return "Miau"

mascota = Perro("Luna")
print(mascota.hablar())   # → Guau
```
